template <class... Ts> struct overloaded
  : Ts... { using Ts::operator()...; };
using Field =
    std::variant<int, double, std::string>;
int main() {
  Field price = 101.75;
  std::visit(overloaded{
    [](int v) { std::cout << "int " << v; },
    [](const std::string& s) {
      std::cout << "text " << s; },
  }, price);
}

std::visit(overloaded{
  [](int v) { std::cout << "int " << v; },
  [](double v) { std::cout << v; },
  [](const std::string& s) {
    std::cout << "text " << s; },
  [](const auto& x) {
    static_assert(sizeof(x) == 0, "unhandled");
  },
}, price);                       // 101.75

int main() {
  std::variant<int, std::string> field = 42;
  int& qty = std::get<int>(field);

  field = std::string(
      "waiting-for-confirmation-reply");
  std::cout << qty << '\n';
}

int qty = std::get<int>(field);  // a copy
field = std::string(
    "waiting-for-confirmation-reply");
std::cout << qty << '\n';        // 42

if (auto* p = std::get_if<int>(&field))
  std::cout << *p;               // not printed

struct Order {
  explicit Order(int id) : id(id) {}
  int id;
};

int main() {
  std::variant<Order, std::string> slot;
  slot = Order{5};
  std::cout << std::get<Order>(slot).id << '\n';
}

std::variant<std::monostate, Order,
             std::string> slot;
std::cout << slot.index() << '\n';   // 0

slot = Order{5};
std::cout << std::get<Order>(slot).id; // 5

int main() {
  std::any a = 42;
  long* l = std::any_cast<long>(&a);
  int*  i = std::any_cast<int>(&a);
  std::cout << (l == nullptr) << ' '
            << (i == nullptr) << ' ';
  try {
    std::cout << std::any_cast<unsigned>(a);
  } catch (const std::bad_any_cast&) {
    std::cout << "bad cast";
  }
  std::cout << '\n';
}

